  ('Sait Faik Abasıyanık''ın uzun yıllar yaşadığı ve bugün evinin müze olarak korunduğu ada hangisidir?', 'On which Istanbul island did the writer Sait Faik Abasıyanık live for many years, where his house is now a museum?', '["Burgazada","Heybeliada","Büyükada","Kınalıada"]'::jsonb),
  ('Büyük ve hüzünlü gözlü emekçi kadın portreleriyle tanınan Türk ressam kimdir?', 'Which Turkish painter is known for portraits of working women with large, melancholy eyes?', '["Nuri İyem","Fahrelnissa Zeid","Burhan Doğançay","Erol Akyavaş"]'::jsonb),
  ('Neşet Ertaş''ın babası ve ilk ustası olan bozlak ustası kimdir?', 'Who was the father and first teacher of the folk musician Neşet Ertaş?', '["Muharrem Ertaş","Hacı Taşan","Çekiç Ali","Mahzuni Şerif"]'::jsonb),
  ('Tarkan''ın ''Şımarık'' şarkısının söz ve müziği kime aittir?', 'Who wrote the words and music of Tarkan''s song ''Şımarık'' (''Kiss Kiss'')?', '["Sezen Aksu","Nazan Öncel","Ozan Çolakoğlu","Aşkın Nur Yengi"]'::jsonb),
  ('Osmanlı''nın ilk resmî gazetesi Takvim-i Vekayi hangi padişah döneminde yayımlanmaya başlamıştır?', 'Under which sultan did the first official Ottoman newspaper, Takvim-i Vekayi, begin publication?', '["Mahmud II","Selim III","Abdulmejid","Abdulaziz"]'::jsonb),
  ('1956 Melbourne Olimpiyatları''nda altın madalya kazanan güreşçi Hamit Kaplan hangi stilde güreşiyordu?', 'In which style did wrestler Hamit Kaplan compete when he won Olympic gold at Melbourne 1956?', '["Freestyle","Greco-Roman","Karakucak","Oil wrestling"]'::jsonb),
  ('Türk resminde modernleşmeyi savunan ''D Grubu'' hangi yıl kurulmuştur?', 'In which year was the ''D Group'', which championed modernism in Turkish painting, founded?', '["1933","1923","1941","1950"]'::jsonb),
  ('İstanbul''daki Dördüncü Vakıf Han''ın mimarı olan Birinci Ulusal Mimarlık akımının öncüsü kimdir?', 'Which pioneer of the First National Architectural Movement designed the Fourth Vakıf Han in Istanbul?', '["Mimar Kemaleddin","Vedat Tek","Sedad Hakkı Eldem","Alexandre Vallaury"]'::jsonb),
  ('Osman Hamdi Bey''in ''Kaplumbağa Terbiyecisi'' tablosu bugün İstanbul''da hangi müzede sergilenir?', 'In which Istanbul museum is Osman Hamdi Bey''s painting ''The Tortoise Trainer'' displayed today?', '["Pera Museum","Istanbul Modern","Sakıp Sabancı Museum","Archaeology Museum"]'::jsonb),
  ('Hidayet Türkoğlu NBA kariyerine 2000 yılında hangi takımda başlamıştır?', 'With which team did Hidayet ''Hedo'' Türkoğlu begin his NBA career in 2000?', '["Sacramento Kings","Orlando Magic","Toronto Raptors","Phoenix Suns"]'::jsonb),
  ('İngilizcedeki ''Thursday'' (perşembe) adı hangi İskandinav tanrısından gelir?', 'The English word ''Thursday'' is named after which Norse god?', '["Thor","Odin","Tyr","Frigg"]'::jsonb),
  ('Dünyada en çok yetiştirilen iki kahve türü arabika ve hangisidir?', 'The two most widely grown coffee species are arabica and which other?', '["Robusta","Mocha","Colombian","Espresso"]'::jsonb),
  ('Değerli taşlarda kullanılan 1 karat kaç gramdır?', 'How many grams is one carat, as used for gemstones?', '["0.2","0.1","0.5","1"]'::jsonb),
  ('Standart 3x3 Rubik küpünün her bir yüzünde kaç kare bulunur?', 'How many squares are on each face of a standard 3x3 Rubik''s Cube?', '["9","6","8","12"]'::jsonb),
  ('Monopoly''nin özgün ABD sürümündeki sokak adları hangi şehirden alınmıştır?', 'The street names in the original US version of Monopoly come from which city?', '["Atlantic City","Las Vegas","New York","San Francisco"]'::jsonb),
  ('Bir tarot destesinde ''Büyük Arkana'' kaç karttan oluşur?', 'How many cards make up the ''Major Arcana'' in a tarot deck?', '["22","21","24","78"]'::jsonb),
  ('Evlilik yıldönümlerinde 50. yıl geleneksel olarak hangi malzemeyle anılır?', 'Traditionally, which material is associated with the 50th wedding anniversary?', '["Gold","Silver","Diamond","Pearl"]'::jsonb),
  ('''&'' işareti (ampersand) aslen hangi Latince sözcüğün harflerinin birleşmesinden doğmuştur?', 'The ''&'' sign (ampersand) originally developed from joining the letters of which Latin word?', '["Et","Ad","In","Ex"]'::jsonb),
  ('''LEGO'' adı Danca ''leg godt'' ifadesinden gelir; bu ifade ne anlama gelir?', 'The name ''LEGO'' comes from the Danish ''leg godt''. What does it mean?', '["Play well","Build together","Little brick","Dream big"]'::jsonb),
  ('Ernő Rubik ünlü küpünü icat ettiğinde hangi alanda öğretim üyesiydi?', 'When Ernő Rubik invented his famous cube, in which field was he a lecturer?', '["Architecture","Mathematics","Physics","Chemistry"]'::jsonb)
  ) v(soru, en_soru, en_secenekler)
  join public.questions q on q.soru = v.soru and q.created_at >= transaction_timestamp()
on conflict (question_id, dil) do nothing;

-- ---------------------------------------------------- Çevrilmeyenler
insert into public.ceviri_atlanan (question_id, dil, neden, kod)
select q.id, 'en', v.neden, 'cevrilemez'
  from (values
  ('2005''te Yeni Türk Lirası''na geçilirken paradan kaç sıfır atılmıştır?', 'Türk para reformuna özgü yerel bilgi; İngilizce oyuncu için bağlamsız.')
  ) v(soru, neden)
  join public.questions q on q.soru = v.soru and q.created_at >= transaction_timestamp()
on conflict (question_id, dil) do nothing;

-- ---------------------------------------------------- Karıştırma (TR + EN aynı permütasyon)
drop table if exists pg_temp._parti_karistir;
create temp table _parti_karistir as
select q.id, array_agg(s.idx order by s.rnd) as perm
  from public.questions q
  cross join lateral (
    select (ordinality - 1)::int as idx, random() as rnd
      from jsonb_array_elements(q.secenekler) with ordinality
  ) s
 where q.created_at >= transaction_timestamp()
 group by q.id;

update public.questions q
   set secenekler = (select jsonb_agg(q.secenekler -> u.p order by u.o)
                       from unnest(k.perm) with ordinality u(p, o)),
       dogru_cevap = (array_position(k.perm, q.dogru_cevap::int) - 1)::smallint
  from _parti_karistir k
 where q.id = k.id;

update public.question_translations t
   set secenekler = (select jsonb_agg(t.secenekler -> u.p order by u.o)
                       from unnest(k.perm) with ordinality u(p, o))
  from _parti_karistir k
 where t.question_id = k.id;

drop table if exists pg_temp._parti_karistir;
